import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Cv-B11KK.js";const b=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1790615514000}'),n={name:"roadmap.md"};function i(s,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p class="meta"><strong>Current:</strong> v0.2.0 · <strong>Next:</strong> after v0.2 · <strong>Updated:</strong> 2026-09-28</p><p>What&#39;s next for bbtex, roughly in order. v0.2 is about two things: meeting documents that come from TeXShop, LaTeXTools or Overleaf where they are, and explaining errors in plain English. Nothing here is promised by a date; it&#39;s vibe coded, so it moves when I have time to try things out.</p><h2 id="finishing-v0-1-0" tabindex="-1">Finishing v0.1.0 <a class="header-anchor" href="#finishing-v0-1-0" aria-label="Permalink to &quot;Finishing v0.1.0&quot;">​</a></h2><p>v0.1.0 is <a href="https://github.com/LouLouLibs/bbtex/releases/tag/v0.1.0" target="_blank" rel="noreferrer">released</a> (2026-09-25). The repository is public and these docs are at <a href="https://louloulibs.github.io/bbtex/" target="_blank" rel="noreferrer">louloulibs.github.io/bbtex</a>; a copy is mirrored to UMN&#39;s GitHub (login required). Still to do:</p><ul><li><strong>Walk through a clean install</strong> on a fresh macOS account, following the <a href="./install">clean install walkthrough</a> exactly.</li><li><strong>Sign and notarize the binary.</strong> Until bbtex is signed with an Apple Developer ID and notarized, a browser download is quarantined and blocked; users have to clear it with <code>xattr</code> (the walkthrough and Doctor explain how).</li></ul><h2 id="v0-2" tabindex="-1">v0.2 <a class="header-anchor" href="#v0-2" aria-label="Permalink to &quot;v0.2&quot;">​</a></h2><p>v0.2.0 meets TeXShop, LaTeXTools and Overleaf documents where they are. Tracked in the <a href="https://github.com/LouLouLibs/bbtex/milestone/1" target="_blank" rel="noreferrer">v0.2 milestone</a>, with <a href="https://github.com/LouLouLibs/bbtex/issues/34" target="_blank" rel="noreferrer">#34</a> as the tracking issue.</p><ul><li><strong>Magic comments bbtex doesn&#39;t apply are reported, never dropped silently</strong> (<a href="https://github.com/LouLouLibs/bbtex/issues/29" target="_blank" rel="noreferrer">#29</a>). Doctor lists every <code>% !TEX</code> and <code>% !BIB</code> comment as used, mapped or ignored, and builds name the ones that don&#39;t fully apply with a <code>[bbtex]</code> note.</li><li><strong>Build settings in comments</strong> (<a href="https://github.com/LouLouLibs/bbtex/issues/30" target="_blank" rel="noreferrer">#30</a>): <code>options</code>, <code>parameter</code>, <code>output_directory</code> and <code>% !BIB TS-program</code> map onto bbtex&#39;s settings; <code>.bbtex</code> wins, and shell escape only comes from <code>.bbtex</code>. See <a href="./project-builds#build-settings-in-comments">build settings in comments</a>.</li><li><strong>Plain-English error hints</strong> (<a href="https://github.com/LouLouLibs/bbtex/issues/31" target="_blank" rel="noreferrer">#31</a>): a <code>[bbtex]</code> line under the errors bbtex recognises, in LaTeX Results and <code>bbtex parse-log</code>. TeX&#39;s own message is never changed.</li><li><strong>The main file without a root comment</strong> (<a href="https://github.com/LouLouLibs/bbtex/issues/32" target="_blank" rel="noreferrer">#32</a>): a file that names no main document builds the one document nearby that includes it, as in an Overleaf project. See <a href="./project-builds#without-a-root-comment">without a root comment</a>.</li><li><strong>Project <code>latexmkrc</code></strong> (<a href="https://github.com/LouLouLibs/bbtex/issues/33" target="_blank" rel="noreferrer">#33</a>): read as latexmk always does; bbtex keeps its output folder, auxiliary folder and engine, and says so. An rc <code>$aux_dir</code> no longer hides build errors. See <a href="./project-builds#a-project-latexmkrc">a project <code>latexmkrc</code></a>.</li></ul><h2 id="after-v0-2" tabindex="-1">After v0.2 <a class="header-anchor" href="#after-v0-2" aria-label="Permalink to &quot;After v0.2&quot;">​</a></h2><p>Smaller things already on the list:</p><ul><li><strong>Unsaved buffers.</strong> Previews and the outline read saved files; snapshot unsaved dependency edits instead.</li><li><strong>Outline state</strong> that survives closing and reopening the window.</li><li><strong>Open the file under <code>\\input</code>/<code>\\include</code></strong> at the cursor.</li><li><strong>A richer citation picker.</strong></li><li><strong>Compile on save</strong> (opt-in), reusing the cancellation and one-build-per-project machinery. It has to replace ⌘K builds rather than run alongside them.</li><li><strong>Word count</strong> via <code>texcount</code>.</li><li><strong>Live selection polish</strong>: measure capturing the text before the selection on multi-megabyte documents; clearer wording when a save cancels a render; stop renders queued behind a long build when live mode is turned off; ignore a literal <code>\\begin{document}</code> inside a comment when detecting math.</li><li><strong>Tests</strong>: move the six Python checks that only exercise the binary (project builds, preview, preview cancellation, real engines, Tectonic, TexLab) to dune cram tests where practical, and make <code>check_live_preview.py</code> wait on state like <code>check_live_selection.py</code> does, since it flakes on timing.</li></ul><h2 id="not-planned" tabindex="-1">Not planned <a class="header-anchor" href="#not-planned" aria-label="Permalink to &quot;Not planned&quot;">​</a></h2><p>To be upfront about what bbtex won&#39;t try to be:</p><ul><li>Overleaf&#39;s collaboration features: real-time co-editing, comments, track changes. Git and BBEdit cover history.</li><li>A rich-text or visual editor, cloud builds, or built-in AI features.</li><li>Running TeXShop engine scripts, or viewers other than Skim.</li><li>Reimplementing completion that TexLab already provides.</li></ul><p>Have an idea, or hit something that isn&#39;t here? <a href="https://github.com/LouLouLibs/bbtex/issues" target="_blank" rel="noreferrer">Open an issue</a>.</p>',16)])])}const p=t(n,[["render",i]]);export{b as __pageData,p as default};
